function Invoke-CategoryManagementSmokeTests { param([string]$Username="",[string]$Password="")
    if(-not$Username-or-not$Password){Write-TestSkipped "Category management tests";return};$login=Invoke-ApiRequest "POST" "/api/v1/auth/login" -Body @{username=$Username;password=$Password};if($login.StatusCode-ne 200){Write-TestSkipped "Category management tests";return};$headers=@{Authorization="Bearer $((Convert-JsonResponse $login 'Category management login contains valid JSON').token)"};$suffix=[DateTimeOffset]::UtcNow.ToUnixTimeMilliseconds();$id=$null
    try{$r=Invoke-ApiRequest "POST" "/api/v1/categories" -Headers $headers -Body @{name="Smoke category $suffix"};if(-not(Assert-StatusCode $r 201 "Manager can create a category")){return};$d=Convert-JsonResponse $r "Created category contains valid JSON";$id=$d.data.id;if($id-and$d.data.slug){Write-TestSuccess "Created category follows the V1 contract"}else{Write-TestFailure "Created category follows the V1 contract";return};$r=Invoke-ApiRequest "PATCH" "/api/v1/categories/$id" -Headers $headers -Body @{name="Updated smoke category $suffix"};if(Assert-StatusCode $r 200 "Manager can update a category"){if((Convert-JsonResponse $r "Updated category contains valid JSON").data.name-eq"Updated smoke category $suffix"){Write-TestSuccess "Updated category contains the new name"}else{Write-TestFailure "Updated category contains the new name"}};$r=Invoke-ApiRequest "DELETE" "/api/v1/categories/$id" -Headers $headers;if(Assert-StatusCode $r 204 "Manager can delete an unused category"){$id=$null}}finally{if($null-ne$id){$null=Invoke-ApiRequest "DELETE" "/api/v1/categories/$id" -Headers $headers}}
}
